+
+async function handleListSessions(
+  ws: WebSocket,
+  session: ChatSession,
+  sessionStore: SessionStore | undefined,
+  message: ListSessionsMessage,
+  options: MessageHandlerOptions = {}
+): Promise<void> {
+  if (options.history?.enabled === false) {
+    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation listing is not supported');
+    return;
+  }
+  if (!sessionStore?.listFor) {
+    sendJson(ws, {type: 'session_list', sessions: []});
+    return;
+  }
+
+  try {
+    const summaries = await sessionStore.listFor(session.userId, {
+      limit: message.limit,
+      before: message.before,
+    });
+    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSessionSummaryFrame)});
+  } catch (error) {
+    const detail = error instanceof Error ? error.message : 'Unknown error';
+    log.error('ws', 'failed to list sessions', {userId: session.userId, error: detail});
+    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
+  }
+}
+
+function toSessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
+  return {
+    ...summary,
+    createdAt: summary.createdAt.toISOString(),
+    updatedAt: summary.updatedAt.toISOString(),
+  };
 }

